    def ser(vals, L, R):
        out = [str(vals[0])]
        q = [0]
        h = 0
        while h < len(q):
            x = q[h]
            h += 1
            for c in (L[x], R[x]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def fmt(vals, L, R, target):
        return ser(vals, L, R) + '\n' + str(target)

    def rand_tree(n, lo, hi):
        L = [-1] * n
        R = [-1] * n
        vals = [rng.randint(lo, hi) for _ in range(n)]
        openn = [0]
        for i in range(1, n):
            j = rng.randrange(len(openn))
            p = openn[j]
            if L[p] == -1 and R[p] == -1:
                if rng.random() < 0.5:
                    L[p] = i
                else:
                    R[p] = i
            elif L[p] == -1:
                L[p] = i
                openn[j] = openn[-1]
                openn.pop()
            else:
                R[p] = i
                openn[j] = openn[-1]
                openn.pop()
            openn.append(i)
        return vals, L, R

    def chain(n, dirs, vals):
        L = [-1] * n
        R = [-1] * n
        for i in range(n - 1):
            if dirs(i):
                L[i] = i + 1
            else:
                R[i] = i + 1
        return vals, L, R

